import{_ as t,o,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen 선별 모델 게이트웨이 — 공식 입구, 무료 모델, 유료 안내, MiniTavern 입력법.","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen 선별 모델 게이트웨이 — 공식 입구, 무료 모델, 유료 안내, MiniTavern 입력법.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen 선별 모델 게이트웨이 — 공식 입구, 무료 모델, 유료 안내, MiniTavern 입력법."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"ko/free-cloud/opencode-zen.md","filePath":"ko/free-cloud/opencode-zen.md","lastUpdated":1787224147000}'),a={name:"ko/free-cloud/opencode-zen.md"};function n(i,e,l,c,s,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p><a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a> 팀의 <strong>AI 게이트웨이</strong>: 선별·검증된 코딩 지향 모델, 요청 과금; 일부 <strong>Free（기간/상한 내 무료）</strong> 텍스트 모델도 제공합니다. OpenCode 밖 클라이언트（MiniTavern 포함）와 공유 가능. 공식: <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen 문서</a>.</p><blockquote><p>Zen은 <strong>영구 무료 전용</strong>이 아닙니다. 대부분 플래그십은 종량이며 결제/충전이 흔합니다. 아래 「무료 모델」은 한도 내 체험용. 정책은 공식 기준.</p></blockquote><h2 id="공식과-입구" tabindex="-1">공식과 입구 <a class="header-anchor" href="#공식과-입구" aria-label="Permalink to &quot;공식과 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>자원</th><th>주소</th></tr></thead><tbody><tr><td>Zen 소개</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>로그인 / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>문서</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>모델 메타</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL（OpenAI 호환）</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="무료-받기" tabindex="-1">무료 받기 <a class="header-anchor" href="#무료-받기" aria-label="Permalink to &quot;무료 받기&quot;">​</a></h2><ol><li><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a>（GitHub / Google）로그인.</li><li>콘솔 안내에 따라 <strong>API Key</strong> 생성. 결제 정보 요구가 흔함; 무료만 쓰려면 자동 충전 끔을 먼저 확인.</li><li>MiniTavern <strong>Custom (OpenAI)</strong>, Base URL <code>https://opencode.ai/zen/v1</code>, 모델은 아래 <strong>Free</strong> ID.</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>무료</td><td>일부 모델 가격 <strong>Free</strong>（OpenCode 상한 내）; 피드백용, 언제든 조정·중단 가능</td></tr><tr><td>유료</td><td>종량; 잔액 $5 미만 시 기본 자동 충전 $20（콘솔에서 변경/해제）</td></tr><tr><td>카드</td><td>공식 「작동 방식」에 결제 정보 추가; 콘솔 실제 기준</td></tr><tr><td>프라이버시</td><td>무료（Big Pickle, MiMo Free, Hy3, Nemotron Free, Muse Contributor Free）는 로그로 모델 개선 가능; Nemotron은 NVIDIA 체험 — 비밀 전송 금지</td></tr></tbody></table><p>전체 가격·폐기: <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E4%BB%B7" target="_blank" rel="noreferrer">Zen · 가격</a>.</p><h2 id="모델-목록" tabindex="-1">모델 목록 <a class="header-anchor" href="#모델-목록" aria-label="Permalink to &quot;모델 목록&quot;">​</a></h2><p>모델 ID <strong>대소문자 구분</strong>. Zen은 벤더별 경로가 다름: <code>/chat/completions</code>, <code>/responses</code>, <code>/messages</code> 또는 Gemini 전용. MiniTavern **Custom (OpenAI)**는 Chat Completions — 아래 <strong>OpenAI 호환</strong> 행을 우선.</p><p>전체: <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E7%82%B9" target="_blank" rel="noreferrer">Zen · 엔드포인트</a>; <code>GET https://opencode.ai/zen/v1/models</code>.</p><h3 id="텍스트-·-무료-먼저-시도" tabindex="-1">텍스트 · 무료（먼저 시도） <a class="header-anchor" href="#텍스트-·-무료-먼저-시도" aria-label="Permalink to &quot;텍스트 · 무료（먼저 시도）&quot;">​</a></h3><p>모두 <code>…/v1/chat/completions</code>（Muse Contributor Free만 Responses）.</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>Xiaomi MiMo V2.5 무료</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>은닉 모델, 무료</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron 체험, 비밀 금지</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>동일</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>기여자 무료; <code>/responses</code> — <strong>MiniTavern 테스트에 부적합할 수 있음</strong>, Meta 모델 학습 허용</td></tr></tbody></table><h3 id="텍스트-·-유료-openai-호환-선택" tabindex="-1">텍스트 · 유료 OpenAI 호환（선택） <a class="header-anchor" href="#텍스트-·-유료-openai-호환-선택" aria-label="Permalink to &quot;텍스트 · 유료 OpenAI 호환（선택）&quot;">​</a></h3><p>충전 후 같은 Base URL:</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek（Peak / Off-Peak）</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>Zhipu GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="기타-프로토콜-minitavern-주의" tabindex="-1">기타 프로토콜（MiniTavern 주의） <a class="header-anchor" href="#기타-프로토콜-minitavern-주의" aria-label="Permalink to &quot;기타 프로토콜（MiniTavern 주의）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>유형</th><th>예시 ID</th><th>엔드포인트</th></tr></thead><tbody><tr><td>GPT</td><td><code>gpt-5.5</code>, <code>gpt-5.4-nano</code> 등</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude</td><td><code>claude-sonnet-4-6</code>, <code>claude-haiku-4-5</code> 등</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini</td><td><code>gemini-3-flash</code> 등</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>위는 MiniTavern 기본 OpenAI Chat Completions와 <strong>경로가 다름</strong>. 롤플레이는 무료 또는 위 OpenAI 호환. Claude는 App <strong>Claude(Anthropic)</strong> 공식 Key, 또는 <a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a> 등 통합 OpenAI 게이트웨이.</p><h3 id="이미지-비디오" tabindex="-1">이미지 / 비디오 <a class="header-anchor" href="#이미지-비디오" aria-label="Permalink to &quot;이미지 / 비디오&quot;">​</a></h3><p>Zen 문서는 <strong>언어 모델</strong> 중심, <strong>독립 무료 이미지/비디오 없음</strong>. 이미지: <a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a> 또는 <a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 이미지</a>.</p><h2 id="minitavern-입력" tabindex="-1">MiniTavern 입력 <a class="header-anchor" href="#minitavern-입력" aria-label="Permalink to &quot;MiniTavern 입력&quot;">​</a></h2><p>일반: <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>.</p><p>경로: <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong></p><ol><li><strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://opencode.ai/zen/v1</code></li><li>API Key</li><li>모델 <code>mimo-v2.5-free</code>（또는 다른 Free / chat 호환）</li><li><strong>테스트</strong> → 성공 후 기본값</li></ol><blockquote><p>실패 시: GPT Responses / Claude Messages 전용 ID가 아닌지; 자동 충전 끄고 무료 재시도; <a href="/ultra_guides/ko/manual/errors">오류</a>.</p></blockquote><h2 id="관련-장" tabindex="-1">관련 장 <a class="header-anchor" href="#관련-장" aria-label="Permalink to &quot;관련 장&quot;">​</a></h2><ul><li><a href="/ultra_guides/ko/free-cloud/">무료 클라우드 개요</a></li><li><a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a> — Key 하나로 다수 <code>*-free</code> + 이미지</li><li><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/ko/manual/model-link">모델 연결</a></li></ul>',30)])])}const m=t(a,[["render",n]]);export{u as __pageData,m as default};
